98:    fn parse(&mut self) -> Result<Vec<Selector>, String> {
99:        let mut sels = vec![];
100:        loop {
101:            if self.cur().is_none() {
102:                break;
103:            }
104:            let f1: OneSelector =
105:                if self.cur() == Some('-') {
106:                    OneSelector::Start
107:                } else {
108:                    self.parse_one()?
109:                };
110:            let f2: Option<OneSelector> =
111:                if self.cur() == Some('-') {
112:                    self.bump();
113:                    Some(if self.is_end_of_selector() {
114:                        OneSelector::End
115:                    } else {
116:                        self.parse_one()?
117:                    })
118:                } else {
119:                    None
120:                };
121:            if !self.is_end_of_selector() {
122:                return Err(format!(
123:                    "Expected end of field but got '{}' instead.",
124:                    self.cur().unwrap()));
125:            }
126:            sels.push(match f2 {
127:                Some(end) => Selector::Range(f1, end),
128:                None => Selector::One(f1),
129:            });
130:            self.bump();
131:        }
132:        Ok(sels)
