86:    wtr.write_record(vec!["field", "value", "count"])?;
87:    let head_ftables = headers.into_iter().zip(tables.into_iter());
88:    for (i, (header, ftab)) in head_ftables.enumerate() {
89:        let mut header = header.to_vec();
90:        if rconfig.no_headers {
91:            header = (i+1).to_string().into_bytes();
92:        }
93:        for (value, count) in args.counts(&ftab).into_iter() {
94:            let count = count.to_string();
95:            let row = vec![&*header, &*value, count.as_bytes()];
96:            wtr.write_record(row)?;
97:        }
98:    }
