119:                    None
120:                };
121:            if !self.is_end_of_selector() {
122:                return Err(format!(
123:                    "Expected end of field but got '{}' instead.",
124:                    self.cur().unwrap()));
125:            }
126:            sels.push(match f2 {
127:                Some(end) => Selector::Range(f1, end),
128:                None => Selector::One(f1),
