    fn with_index(
        &self,
        mut idx: Indexed<fs::File, fs::File>,
    ) -> CliResult<()> {
        let mut wtr = self.wconfig().writer()?;
        self.rconfig().write_headers(&mut *idx, &mut wtr)?;

        let (start, end) = self.range()?;
        if end - start == 0 {
